package com.phall04.gorest.model;

import com.fasterxml.jackson.annotation.JsonIgnoreProperties;
import com.fasterxml.jackson.annotation.JsonInclude;

//Prevents failure if api adds new fields
@JsonIgnoreProperties(ignoreUnknown = true)

//Does NOT include id in the request as this is generated by the api endpoint
@JsonInclude(JsonInclude.Include.NON_NULL)

//Object representation of a GOREST user. For easier JSON conversion
public record User(String id, String name, String email, String status) {}